css:
.aqua-sim-container {
  padding: 24px;
  background: linear-gradient(180deg, #e0f2fe 0%, #bae6fd 60%, #7dd3fc 100%);
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #0c2d48;
}
.aqua-sim-container * { box-sizing: border-box; }

.aqua-sim-header {
  position: relative;
  background: linear-gradient(135deg, #0c4a6e 0%, #075985 50%, #0369a1 100%);
  color: #ffffff;
  border-radius: 18px;
  padding: 30px 32px;
  margin-bottom: 24px;
  box-shadow: 0 14px 32px rgba(7, 89, 133, 0.28);
  overflow: hidden;
}
.aqua-sim-header::after {
  content: '';
  position: absolute;
  right: -60px;
  top: -60px;
  width: 260px;
  height: 260px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(125, 211, 252, 0.45), transparent 70%);
  pointer-events: none;
}
.aqua-sim-header::before {
  content: '';
  position: absolute;
  left: -40px;
  bottom: -40px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.28), transparent 70%);
  pointer-events: none;
}
.aqua-sim-utility-tag {
  display: inline-block;
  background: rgba(255, 255, 255, 0.18);
  padding: 5px 14px;
  border-radius: 999px;
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 10px;
  font-weight: 600;
  border: 1px solid rgba(255, 255, 255, 0.25);
  position: relative;
  z-index: 2;
}
.aqua-sim-header h1 {
  margin: 0 0 6px 0;
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  position: relative;
  z-index: 2;
}
.aqua-sim-subtitle {
  font-size: 0.95rem;
  color: #bae6fd;
  font-weight: 400;
  position: relative;
  z-index: 2;
}
.aqua-sim-period-bar {
  margin-top: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.92rem;
  color: #e0f2fe;
  position: relative;
  z-index: 2;
}
.aqua-sim-period-bar .aqua-sim-period-name {
  margin-left: 14px;
  background: #0ea5e9;
  color: #ffffff;
  padding: 5px 16px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.82rem;
  box-shadow: 0 4px 10px rgba(14, 165, 233, 0.45);
}

.aqua-sim-briefing {
  background: #ffffff;
  border-left: 5px solid #0ea5e9;
  border-radius: 12px;
  padding: 22px 26px;
  margin-bottom: 24px;
  box-shadow: 0 6px 18px rgba(7, 89, 133, 0.10);
}
.aqua-sim-briefing h3 {
  margin: 0 0 12px 0;
  color: #075985;
  font-size: 0.92rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
}
.aqua-sim-briefing-body {
  color: #0c2d48;
  line-height: 1.6;
  font-size: 0.96rem;
}

.aqua-sim-kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}
.aqua-sim-kpi-card {
  background: #ffffff;
  border-radius: 14px;
  padding: 22px 22px 22px 26px;
  box-shadow: 0 8px 18px rgba(7, 89, 133, 0.10);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.aqua-sim-kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 24px rgba(7, 89, 133, 0.14);
}
.aqua-sim-kpi-card::before {
  content: '';
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 5px;
}
.aqua-sim-kpi-card.kpi-irca::before { background: linear-gradient(180deg, #ef4444, #b91c1c); }
.aqua-sim-kpi-card.kpi-budget::before { background: linear-gradient(180deg, #f59e0b, #d97706); }
.aqua-sim-kpi-card.kpi-capacity::before { background: linear-gradient(180deg, #0ea5e9, #0369a1); }
.aqua-sim-kpi-card.kpi-score::before { background: linear-gradient(180deg, #10b981, #047857); }
.aqua-sim-kpi-label {
  color: #475569;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 10px;
  font-weight: 700;
}
.aqua-sim-kpi-value {
  font-size: 1.85rem;
  font-weight: 700;
  color: #0c4a6e;
  line-height: 1.1;
}

.aqua-sim-controls {
  background: #ffffff;
  border-radius: 14px;
  padding: 26px;
  margin-bottom: 24px;
  box-shadow: 0 8px 18px rgba(7, 89, 133, 0.10);
}
.aqua-sim-controls h3 {
  margin: 0 0 18px 0;
  color: #075985;
  font-size: 0.92rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  border-bottom: 2px solid #e0f2fe;
  padding-bottom: 10px;
}
.aqua-sim-panel {
  display: block;
}
.aqua-sim-row {
  margin-bottom: 16px;
}
.aqua-sim-row label {
  display: block;
  color: #0c2d48;
  font-weight: 600;
  font-size: 0.9rem;
  margin-bottom: 6px;
}
.aqua-sim-controls input[type="number"],
.aqua-sim-controls input[type="text"],
.aqua-sim-controls select {
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  color: #0c2d48;
  border-radius: 8px;
  padding: 10px 12px;
  width: 100%;
  font-size: 0.95rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  font-family: inherit;
}
.aqua-sim-controls input[type="number"]:focus,
.aqua-sim-controls input[type="text"]:focus,
.aqua-sim-controls select:focus {
  outline: none;
  border-color: #0ea5e9;
  box-shadow: 0 0 0 3px rgba(14, 165, 233, 0.18);
}
.aqua-sim-controls select option {
  background: #ffffff;
  color: #0c2d48;
}
.aqua-sim-hint {
  display: block;
  margin-top: 6px;
  color: #64748b;
  font-size: 0.78rem;
  font-style: italic;
}
.aqua-sim-actions {
  display: flex;
  gap: 12px;
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid #e0f2fe;
  flex-wrap: wrap;
}
.aqua-sim-actions .btn-primary {
  background: linear-gradient(135deg, #0ea5e9, #0369a1);
  border: none;
  color: #ffffff;
  font-weight: 600;
  padding: 11px 26px;
  border-radius: 8px;
  box-shadow: 0 6px 14px rgba(14, 165, 233, 0.35);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.aqua-sim-actions .btn-primary:hover {
  background: linear-gradient(135deg, #0284c7, #075985);
  transform: translateY(-1px);
  box-shadow: 0 8px 18px rgba(14, 165, 233, 0.4);
}
.aqua-sim-actions .btn-outline-secondary {
  border: 1px solid #cbd5e1;
  color: #475569;
  background: #ffffff;
  border-radius: 8px;
  padding: 11px 18px;
  font-weight: 500;
}
.aqua-sim-actions .btn-outline-secondary:hover {
  background: #f1f5f9;
  color: #0c2d48;
}

.aqua-sim-history {
  background: #ffffff;
  border-radius: 14px;
  padding: 26px;
  margin-bottom: 24px;
  box-shadow: 0 8px 18px rgba(7, 89, 133, 0.10);
  overflow-x: auto;
}
.aqua-sim-history h3 {
  margin: 0 0 16px 0;
  color: #075985;
  font-size: 0.92rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
}
.aqua-sim-history table {
  margin: 0;
  width: 100%;
}
.aqua-sim-history thead th {
  background: #f1f5f9;
  color: #0c2d48;
  font-weight: 700;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-bottom: 2px solid #cbd5e1 !important;
  padding: 10px 12px;
}
.aqua-sim-history tbody td {
  font-size: 0.9rem;
  color: #0c2d48;
  vertical-align: middle;
  padding: 10px 12px;
  border-color: #e2e8f0;
}
.aqua-sim-history tbody tr:nth-child(even) {
  background: #f8fafc;
}

.aqua-sim-charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}
.aqua-sim-chart-card {
  background: #ffffff;
  border-radius: 14px;
  padding: 18px;
  box-shadow: 0 8px 18px rgba(7, 89, 133, 0.10);
  height: 320px;
  position: relative;
}
.aqua-sim-chart-card canvas {
  max-height: 100%;
}

@media (max-width: 768px) {
  .aqua-sim-container { padding: 14px; }
  .aqua-sim-header { padding: 22px 20px; }
  .aqua-sim-header h1 { font-size: 1.2rem; }
  .aqua-sim-subtitle { font-size: 0.85rem; }
  .aqua-sim-kpi-value { font-size: 1.45rem; }
  .aqua-sim-actions { flex-direction: column; }
  .aqua-sim-actions .btn-primary,
  .aqua-sim-actions .btn-outline-secondary { width: 100%; }
}

js:
(function() {
    'use strict';

    class AquaSimAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'San Joaquin del Rio Water Utility';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    population: 9200,
                    populationHorizon: 9200 * Math.pow(1.014, 25),
                    qDesignLs: 0,
                    qHourlyMaxLs: 0,
                    capacityLs: 15.2,
                    irca: 18.7,
                    budgetSpentMillions: 0,
                    budgetCommittedMillions: 0,
                    budgetEnvelopeMillions: 2400,
                    psmvCompliance: 30,
                    ruralReady: false,
                    score: 0,
                    trunkVelocity: 0,
                    trunkHeadLoss: 0,
                    trunkPressure: 0,
                    ircaHistory: [18.7],
                    scoreHistory: [0],
                    flags: [],
                    completedRounds: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    dotacion: 130,
                    ianc: 38,
                    horizon: 25,
                    treatment: 'C',
                    ptar: 'uasb',
                    finance: 'pap',
                    diameter: 200,
                    vereda: 'satellite',
                    breakTanks: 2,
                    iancPlan: 'structured',
                    psmv: 'milestones',
                    frame: 'financial'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            if (period > 4) period = 4;
            for (var i = 1; i <= 4; i++) {
                var p = document.getElementById('panelRound' + i);
                if (p) p.style.display = (i === period) ? 'block' : 'none';
            }
            var brief = document.getElementById('briefingText');
            var roundName = document.getElementById('roundName');
            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
            if (brief) brief.innerHTML = t('briefing_r' + period);
            if (roundName) roundName.textContent = t('round_name_' + period);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var period = state.currentPeriod;

            if (period === 1) {
                var dotEl = document.getElementById('dotacionInput');
                var iancEl = document.getElementById('iancInput');
                var horizonEl = document.getElementById('horizonSelect');
                var dot = dotEl ? parseFloat(dotEl.value) : NaN;
                var ianc = iancEl ? parseFloat(iancEl.value) : NaN;
                var horizon = horizonEl ? parseInt(horizonEl.value, 10) : 25;
                if (isNaN(dot) || dot < 80 || dot > 220) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_dotacion'), 'warning');
                    return false;
                }
                if (isNaN(ianc) || ianc < 20 || ianc > 45) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_ianc'), 'warning');
                    return false;
                }
                decisions.dotacion = dot;
                decisions.ianc = ianc;
                decisions.horizon = horizon;
            } else if (period === 2) {
                var t1 = document.getElementById('treatmentSelect');
                var p1 = document.getElementById('ptarSelect');
                var f1 = document.getElementById('financeSelect');
                if (t1) decisions.treatment = t1.value;
                if (p1) decisions.ptar = p1.value;
                if (f1) decisions.finance = f1.value;
            } else if (period === 3) {
                var dEl = document.getElementById('diameterSelect');
                var vEl = document.getElementById('veredaSelect');
                var bEl = document.getElementById('breakInput');
                if (dEl) decisions.diameter = parseInt(dEl.value, 10);
                if (vEl) decisions.vereda = vEl.value;
                var bt = bEl ? parseInt(bEl.value, 10) : 0;
                if (isNaN(bt) || bt < 0 || bt > 6) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_break'), 'warning');
                    return false;
                }
                decisions.breakTanks = bt;
            } else if (period === 4) {
                var ip = document.getElementById('iancPlanSelect');
                var ps = document.getElementById('psmvSelect');
                var fr = document.getElementById('frameSelect');
                if (ip) decisions.iancPlan = ip.value;
                if (ps) decisions.psmv = ps.value;
                if (fr) decisions.frame = fr.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var notes = [];
            var roundScore = 0;
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (period === 1) {
                var popFinal = ds.population * Math.pow(1.014, d.horizon);
                var dotBruta = d.dotacion / Math.max(0.5, (1 - d.ianc / 100));
                var qMedio = (popFinal * dotBruta) / 86400;
                var k1 = 1.30, k2 = 1.50;
                var qMaxHorario = qMedio * k1 * k2;
                ds.qDesignLs = qMedio;
                ds.qHourlyMaxLs = qMaxHorario;
                ds.populationHorizon = popFinal;

                if (d.dotacion <= 130) {
                    roundScore += 12;
                    notes.push(t('note_dot_ok'));
                } else if (d.dotacion <= 145) {
                    roundScore += 6;
                    notes.push(t('note_dot_high'));
                } else {
                    notes.push(t('note_dot_violation'));
                    if (ds.flags.indexOf('ras_dotacion') === -1) ds.flags.push('ras_dotacion');
                }

                if (d.ianc >= 24 && d.ianc <= 30) {
                    roundScore += 8;
                    notes.push(t('note_ianc_ok'));
                } else if (d.ianc < 24) {
                    roundScore += 2;
                    notes.push(t('note_ianc_low'));
                    if (ds.flags.indexOf('ianc_unrealistic') === -1) ds.flags.push('ianc_unrealistic');
                } else {
                    roundScore += 5;
                    notes.push(t('note_ianc_high'));
                }

                if (d.horizon === 25) {
                    roundScore += 5;
                } else {
                    roundScore += 2;
                    notes.push(t('note_horizon_off'));
                }
            } else if (period === 2) {
                var trtCost = { A: 4800, B: 2600, C: 1900, H: 2100 };
                var ptarCost = { none: 0, pre: 250, uasb: 750, lagoons: 600 };
                var totalCost = (trtCost[d.treatment] || 0) + (ptarCost[d.ptar] || 0);
                var rasCompliant = ds.flags.indexOf('ras_dotacion') === -1;
                var papShare = rasCompliant ? 0.60 : 0.40;
                var papContribution = totalCost * papShare;
                var ownContribution = totalCost - papContribution;
                ds.budgetSpentMillions = totalCost;
                ds.budgetCommittedMillions = ownContribution;

                var ircaMap = { A: 1.5, B: 3.5, C: 4.2, H: 4.5 };
                ds.irca = ircaMap[d.treatment] !== undefined ? ircaMap[d.treatment] : 18.7;

                var capMap = { A: 60, B: 28, C: 30, H: 30 };
                ds.capacityLs = capMap[d.treatment] || 15.2;
                ds.ruralReady = ds.capacityLs >= ds.qHourlyMaxLs;

                if (d.ptar === 'none') ds.psmvCompliance = 10;
                else if (d.ptar === 'pre') ds.psmvCompliance = 35;
                else if (d.ptar === 'uasb') ds.psmvCompliance = 80;
                else if (d.ptar === 'lagoons') ds.psmvCompliance = 70;

                if (ds.irca < 5) {
                    roundScore += 12;
                    notes.push(t('note_irca_ok'));
                } else {
                    notes.push(t('note_irca_fail'));
                    if (ds.flags.indexOf('irca_fail') === -1) ds.flags.push('irca_fail');
                }

                if (ownContribution <= ds.budgetEnvelopeMillions * 0.40) {
                    roundScore += 10;
                    notes.push(t('note_budget_ok'));
                } else if (ownContribution <= ds.budgetEnvelopeMillions) {
                    roundScore += 5;
                    notes.push(t('note_budget_tight'));
                } else {
                    notes.push(t('note_budget_over'));
                    if (ds.flags.indexOf('budget_over') === -1) ds.flags.push('budget_over');
                }

                if (ds.psmvCompliance >= 70) {
                    roundScore += 6;
                } else if (ds.psmvCompliance >= 35) {
                    roundScore += 3;
                } else {
                    if (ds.flags.indexOf('psmv_gap') === -1) ds.flags.push('psmv_gap');
                }

                if (ds.ruralReady) {
                    roundScore += 4;
                } else {
                    notes.push(t('note_rural_gap'));
                }

                if (d.finance === 'vf' || d.finance === 'findeter') {
                    if (ds.flags.indexOf('budget_over') > -1) {
                        roundScore += 3;
                        notes.push(t('note_finance_closes_gap'));
                    }
                }
            } else if (period === 3) {
                var Q = ds.qHourlyMaxLs / 1000;
                var D = d.diameter / 1000;
                var area = Math.PI * D * D / 4;
                var v = area > 0 ? Q / area : 0;
                var L = 4200;
                var C = 150;
                var hf = 0;
                if (Q > 0 && D > 0) {
                    hf = 10.67 * L * Math.pow(Q, 1.852) / (Math.pow(C, 1.852) * Math.pow(D, 4.87));
                }
                var staticHead = 110;
                var availPressure = staticHead - hf;

                if (v > 6) {
                    notes.push(t('note_v_violation'));
                    if (ds.flags.indexOf('velocity_high') === -1) ds.flags.push('velocity_high');
                } else if (v > 5) {
                    roundScore += 3;
                    notes.push(t('note_v_economic'));
                } else if (v >= 0.6) {
                    roundScore += 8;
                    notes.push(t('note_v_ok'));
                } else {
                    roundScore += 4;
                    notes.push(t('note_v_low'));
                }

                if (availPressure < 10) {
                    notes.push(t('note_p_low'));
                    if (ds.flags.indexOf('pressure_low') === -1) ds.flags.push('pressure_low');
                } else if (availPressure > 50 && d.breakTanks < 1) {
                    notes.push(t('note_p_high'));
                    if (ds.flags.indexOf('pressure_high') === -1) ds.flags.push('pressure_high');
                } else {
                    roundScore += 6;
                }

                if (d.vereda === 'satellite') {
                    roundScore += 8;
                    notes.push(t('note_vereda_satellite'));
                } else if (d.vereda === 'pump') {
                    roundScore += 2;
                    notes.push(t('note_vereda_pump'));
                    if (ds.flags.indexOf('vereda_energy') === -1) ds.flags.push('vereda_energy');
                } else {
                    roundScore += 3;
                    notes.push(t('note_vereda_defer'));
                }

                if (d.breakTanks >= 1) roundScore += 3;

                ds.trunkVelocity = v;
                ds.trunkHeadLoss = hf;
                ds.trunkPressure = availPressure;
            } else if (period === 4) {
                if (d.iancPlan === 'structured' || d.iancPlan === 'aggressive') {
                    roundScore += 6;
                    if (d.iancPlan === 'aggressive') roundScore += 2;
                    if (ds.flags.indexOf('ianc_unrealistic') > -1) {
                        notes.push(t('note_plan_recovers_ianc'));
                        ds.flags = ds.flags.filter(function(f) { return f !== 'ianc_unrealistic'; });
                    }
                } else {
                    notes.push(t('note_plan_minimal'));
                    if (d.ianc <= 25 && ds.flags.indexOf('ianc_unrealistic') === -1) {
                        ds.flags.push('ianc_unrealistic');
                    }
                }

                if (d.psmv === 'accelerate') {
                    roundScore += 8;
                    notes.push(t('note_psmv_accelerate'));
                    if (ds.flags.indexOf('psmv_gap') > -1) {
                        ds.flags = ds.flags.filter(function(f) { return f !== 'psmv_gap'; });
                    }
                } else if (d.psmv === 'milestones') {
                    roundScore += 5;
                    if (ds.flags.indexOf('psmv_gap') > -1) {
                        notes.push(t('note_psmv_renegotiated'));
                    }
                } else {
                    roundScore += 1;
                    if (ds.flags.indexOf('psmv_defer') === -1) ds.flags.push('psmv_defer');
                    notes.push(t('note_psmv_defer'));
                }

                if (d.frame === 'community') roundScore += 4;
                else if (d.frame === 'financial') roundScore += 3;
                else roundScore += 3;

                if (ds.flags.indexOf('budget_over') > -1) roundScore -= 4;
                if (ds.flags.indexOf('velocity_high') > -1) roundScore -= 2;
                if (ds.flags.indexOf('pressure_low') > -1) roundScore -= 2;
            }

            ds.score = (ds.score || 0) + roundScore;
            ds.completedRounds = period;
            ds.ircaHistory.push(Math.round(ds.irca * 10) / 10);
            ds.scoreHistory.push(ds.score);

            var self = this;
            // v1.1.0 FIX: capture nextPeriod BEFORE the async. The host increments
            // state.currentPeriod synchronously after calculateResults() returns, so reading it
            // inside the timer was two rounds ahead — _updateBriefing() then revealed the WRONG
            // decision panel (round 3's inputs during round 2, round 4's during round 3).
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 400);

            return {
                period: period,
                round_score: roundScore,
                cumulative_score: ds.score,
                irca: Math.round(ds.irca * 10) / 10,
                budget_committed_m: Math.round(ds.budgetCommittedMillions || 0),
                capacity_ls: Math.round(ds.capacityLs * 10) / 10,
                psmv: ds.psmvCompliance || 0,
                notes: notes.join('<br>')
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
