        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var totalScore = (last.results && last.results.cumulative_score) || 0;
            var finalIrca = (last.results && last.results.irca) !== undefined
                ? last.results.irca : 18.7;
            var t = window.mySimulation.t.bind(window.mySimulation);

            var perfKey = 'perf_at_risk';
            if (totalScore >= 80 && finalIrca < 5) perfKey = 'perf_excellent';
            else if (totalScore >= 60 && finalIrca < 5) perfKey = 'perf_good';
            else if (totalScore >= 40) perfKey = 'perf_acceptable';

            var insights = [];
            if (finalIrca < 5) insights.push(t('insight_irca_ok'));
            else insights.push(t('insight_irca_fail'));

            var ds = (window.mySimulation.state && window.mySimulation.state.domainState) || {};
            if (ds.flags && ds.flags.indexOf('budget_over') > -1) insights.push(t('insight_budget'));
            if (ds.flags && ds.flags.indexOf('psmv_gap') > -1) insights.push(t('insight_psmv'));
            if (ds.flags && ds.flags.indexOf('vereda_energy') > -1) insights.push(t('insight_vereda'));
            if (!ds.flags || ds.flags.length === 0) insights.push(t('insight_clean'));

            return {
                totalScore: totalScore,
                finalIrca: finalIrca,
                performance: t(perfKey),
                insights: insights
            };
        }

